use super::{CompileError, Literal};

pub(super) struct Prototype<'a> {
    pub upvalues: usize,
    pub parameters: usize,
    pub registers: usize,
    pub code: Instructions<'a>,
    pub constants: Vec<Literal>,
}

// The dump stays borrowed until lowering finishes. Decode each checked word
// once at use, without allocating and copying an intermediate instruction Vec.
pub(super) struct Instructions<'a> {
    bytes: &'a [u8],
    little: bool,
}

impl Instructions<'_> {
    pub fn len(&self) -> usize {
        self.bytes.len() / 4
    }
}

pub(super) struct InstructionIter<'a> {
    words: std::slice::ChunksExact<'a, u8>,
    little: bool,
}

impl Iterator for InstructionIter<'_> {
    type Item = u32;
    fn next(&mut self) -> Option<u32> {
        let bytes = self.words.next()?.try_into().expect("four-byte instruction");
        Some(if self.little {
            u32::from_le_bytes(bytes)
        } else {
            u32::from_be_bytes(bytes)
        })
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        self.words.size_hint()
    }
}
impl ExactSizeIterator for InstructionIter<'_> {}

impl<'a> IntoIterator for Instructions<'a> {
    type Item = u32;
    type IntoIter = InstructionIter<'a>;
    fn into_iter(self) -> Self::IntoIter {
        InstructionIter {
            words: self.bytes.chunks_exact(4),
            little: self.little,
        }
    }
}

struct Reader<'a> {
    bytes: &'a [u8],
    at: usize,
    little: bool,
    size_t: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, count: usize) -> Result<&'a [u8], CompileError> {
        let end = self.at.checked_add(count).ok_or(CompileError::InvalidChunk)?;
        let bytes = self.bytes.get(self.at..end).ok_or(CompileError::InvalidChunk)?;
        self.at = end;
        Ok(bytes)
    }

    fn byte(&mut self) -> Result<u8, CompileError> {
        Ok(self.take(1)?[0])
    }

    fn uint(&mut self, width: usize) -> Result<u64, CompileError> {
        let little = self.little;
        let bytes = self.take(width)?;
        Ok(if little {
            bytes.iter().rev().fold(0, |n, b| (n << 8) | u64::from(*b))
        } else {
            bytes.iter().fold(0, |n, b| (n << 8) | u64::from(*b))
        })
    }

    fn count(&mut self) -> Result<usize, CompileError> {
        let n = self.uint(4)?;
        if n > i32::MAX as u64 || n as usize > self.bytes.len() - self.at {
            return Err(CompileError::InvalidChunk);
        }
        Ok(n as usize)
    }

    fn string(&mut self) -> Result<Option<Box<[u8]>>, CompileError> {
        let n = usize::try_from(self.uint(self.size_t)?).map_err(|_| CompileError::InvalidChunk)?;
        if n == 0 {
            return Ok(None);
        }
        let bytes = self.take(n)?;
        if bytes.last() != Some(&0) {
            return Err(CompileError::InvalidChunk);
        }
        Ok(Some(bytes[..n - 1].into()))
    }

    fn skip_string(&mut self) -> Result<(), CompileError> {
        let n = usize::try_from(self.uint(self.size_t)?).map_err(|_| CompileError::InvalidChunk)?;
        if n != 0 && self.take(n)?.last() != Some(&0) {
            return Err(CompileError::InvalidChunk);
        }
        Ok(())
    }
}

pub(super) fn decode(bytes: &[u8]) -> Result<Prototype<'_>, CompileError> {
    let mut r = Reader {
        bytes,
        at: 0,
        little: true,
        size_t: 8,
    };
    if r.take(6)? != b"\x1bLua\x51\0" {
        return Err(CompileError::InvalidChunk);
    }
    r.little = match r.byte()? {
        0 => false,
        1 => true,
        _ => return Err(CompileError::InvalidChunk),
    };
    if r.byte()? != 4 {
        return Err(CompileError::InvalidChunk);
    }
    r.size_t = match r.byte()? {
        4 => 4,
        8 => 8,
        _ => return Err(CompileError::InvalidChunk),
    };
    if r.take(3)? != [4, 8, 0] {
        return Err(CompileError::InvalidChunk);
    }
    r.skip_string()?;
    r.take(8)?; // Source line range.
    let upvalues = usize::from(r.byte()?);
    let parameters = usize::from(r.byte()?);
    if r.byte()? != 0 {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "varargs",
        });
    }
    let registers = usize::from(r.byte()?);
    if !(1..=250).contains(&registers) || parameters > registers {
        return Err(CompileError::InvalidChunk);
    }
    let count = r.count()?;
    if count == 0 || count > 4096 {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "instruction count",
        });
    }
    let little = r.little;
    let code = Instructions {
        bytes: r.take(count.checked_mul(4).ok_or(CompileError::InvalidChunk)?)?,
        little,
    };
    let count = r.count()?;
    if count > 4096 {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "constant count",
        });
    }
    let mut constants = Vec::with_capacity(count);
    for _ in 0..count {
        constants.push(match r.byte()? {
            0 => Literal::Nil,
            1 => Literal::Boolean(match r.byte()? {
                0 => false,
                1 => true,
                _ => return Err(CompileError::InvalidChunk),
            }),
            3 => Literal::Number(f64::from_bits(r.uint(8)?)),
            4 => Literal::Bytes(r.string()?.ok_or(CompileError::InvalidChunk)?),
            _ => return Err(CompileError::InvalidChunk),
        });
    }
    if r.count()? != 0 {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "nested closures",
        });
    }
    let lines = r.count()?;
    r.take(lines.checked_mul(4).ok_or(CompileError::InvalidChunk)?)?;
    for _ in 0..r.count()? {
        r.skip_string()?;
        r.take(8)?;
    }
    for _ in 0..r.count()? {
        r.skip_string()?;
    }
    if r.at != bytes.len() {
        return Err(CompileError::InvalidChunk);
    }
    Ok(Prototype {
        upvalues,
        parameters,
        registers,
        code,
        constants,
    })
}

//! Share immutable code without merging callback slots or mutable state.
use super::*;
use rustc_hash::{FxHashMap, FxHasher};
use std::hash::{Hash, Hasher};

fn string_hash(strings: &Strings) -> u64 {
    let mut hash = FxHasher::default();
    strings[..].hash(&mut hash);
    hash.finish()
}

fn fingerprint(code: &Code, strings: u64) -> u64 {
    let mut hash = FxHasher::default();
    code.ops.hash(&mut hash);
    code.parameters.hash(&mut hash);
    code.cells.hash(&mut hash);
    code.tables.hash(&mut hash);
    code.registers.hash(&mut hash);
    code.clear_registers.hash(&mut hash);
    strings.hash(&mut hash);
    hash.finish()
}

fn same(a: &Code, b: &Code) -> bool {
    a.registers == b.registers
        && a.clear_registers == b.clear_registers
        && a.ops == b.ops
        && a.parameters == b.parameters
        && a.cells == b.cells
        && a.tables == b.tables
        && a.strings[..] == b.strings[..]
}

pub(super) fn code(programs: &mut [Program]) {
    let first = &programs[0].0;
    if programs.iter().all(|p| Arc::ptr_eq(first, &p.0)) {
        return;
    }
    // Normalized byte-cell programs share one arena. Hash its contents once.
    let shared = programs
        .iter()
        .all(|p| first.strings.shared_with(&p.0.strings))
        .then(|| string_hash(&first.strings));
    let mut seen = FxHashMap::<u64, usize>::with_capacity_and_hasher(programs.len(), Default::default());
    for index in 0..programs.len() {
        let hash = fingerprint(
            &programs[index].0,
            shared.unwrap_or_else(|| string_hash(&programs[index].0.strings)),
        );
        if let Some(&existing) = seen.get(&hash) {
            // A fingerprint is only a candidate. Exact value/bit equality is
            // required, and a collision may safely leave other code unshared.
            if same(&programs[existing].0, &programs[index].0) {
                programs[index] = programs[existing].clone();
            }
        } else {
            seen.insert(hash, index);
        }
    }
}

