            let Datum::Number(actual) = machine.run(&inputs, |_, _| panic!("no action")).unwrap() else {
                panic!("number result")
            };
            assert_eq!(actual.to_bits(), expected.to_bits());
        }
        let Some(Datum::Number(n)) = untouched.cell(0) else {
